// ===== SW-019 Cross-Encoder Reranker (§259/§465) =====
// R-12/§305: rerank is GATED by rerankerEnabled and requires crossEncoderModel.
// WF-002 only routes here when the gate is true, but the guard is repeated at the
// point of use so the sub-workflow cannot silently no-op if called directly.
const inp = $('When Called by WF-002').first().json;
const cfg = inp.config || {};
if (!cfg.rerankerEnabled) {
  throw new Error('SW-019 called while rerankerEnabled=false. WF-002 must not route here ' +
    'when the gate is off; a silent pass-through would misreport statistics.reranked.');
}
if (!cfg.crossEncoderModel) {
  throw new Error('SW-019: rerankerEnabled=true but crossEncoderModel is empty (§465). ' +
    'Set the model in configuration/retrieval.yaml before enabling rerank.');
}
throw new Error('SW-019: no cross-encoder provider is configured in this deployment. ' +
  'Rerank is disabled by canonical configuration (rerankerEnabled=false); enabling it ' +
  'requires provisioning a cross-encoder first.');
